// Original bevelled armor, shared PBR panel atlas, and instanced archaeological details.
export class DetailScene {
 constructor(T){this.T=T;this.geometries=new Map;this.texture=this.atlas();this.panel=new T.Standard({color:'#a6bdc9',metalness:.68,roughness:.42,map:this.texture,bumpMap:this.texture,bumpScale:.009});this.dark=new T.Standard({color:'#264858',metalness:.36,roughness:.72});this.stone=new T.Standard({color:'#31505a',metalness:.08,roughness:.91,map:this.texture});this.edge=new T.Standard({color:'#86b0ae',metalness:.45,roughness:.48});this.unit=new T.Object;this.block=new T.Box(.06,.08,.07);this.rib=new T.Box(.025,.012,.16)}
 atlas(){const a=document.createElement('canvas');a.width=a.height=1024;const c=a.getContext('2d');c.fillStyle='#b9c4ca';c.fillRect(0,0,1024,1024);for(let y=0;y<1024;y+=128)for(let x=0;x<1024;x+=128){c.fillStyle=(x+y)%256?'#c4ccd0':'#acbcc4';c.fillRect(x+3,y+3,122,122);c.strokeStyle='#566875';c.lineWidth=2;c.strokeRect(x+4,y+4,120,120);c.strokeStyle='#edf2f1';c.lineWidth=1;c.beginPath();c.moveTo(x+6,y+120);c.lineTo(x+6,y+6);c.lineTo(x+119,y+6);c.stroke();for(let j=0;j<4;j++){c.fillStyle='#657783';c.fillRect(x+12+j*25,y+111,3,3)}c.fillStyle='#7e929e';for(let j=0;j<8;j++)c.fillRect(x+77+j*4,y+17,2,24)}const t=new this.T.Texture(a);t.colorSpace='srgb';t.anisotropy=4;return t}
 shape(kind){if(this.geometries.has(kind))return this.geometries.get(kind);const profiles={dart:[[0,-.42],[.06,-.12],[.16,.2],[.09,.3],[0,.2],[-.09,.3],[-.16,.2],[-.06,-.12]],orb:[[0,-.29],[.19,-.2],[.29,-.03],[.26,.16],[.13,.28],[-.13,.28],[-.26,.16],[-.29,-.03],[-.19,-.2]],carrier:[[0,-.3],[.12,-.22],[.16,-.05],[.28,-.18],[.35,-.08],[.35,.28],[.18,.31],[.1,.2],[-.1,.2],[-.18,.31],[-.35,.28],[-.35,-.08],[-.28,-.18],[-.16,-.05],[-.12,-.22]],relay:[[0,-.3],[.1,-.14],[.32,-.2],[.23,.04],[.3,.18],[.14,.14],[0,.31],[-.14,.14],[-.3,.18],[-.23,.04],[-.32,-.2],[-.1,-.14]]};const points=profiles[kind]||[[0,-.34],[.08,-.1],[.31,.11],[.27,.26],[.1,.18],[0,.25],[-.1,.18],[-.27,.26],[-.31,.11],[-.08,-.1]];const s=new this.T.Shape;points.forEach(([x,y],i)=>i?s.lineTo(x,y):s.moveTo(x,y));s.closePath();const geo=new this.T.Extrude(s,{depth:.075,bevelEnabled:true,bevelSize:.018,bevelThickness:.015,bevelSegments:3,steps:1});geo.rotateX(Math.PI/2);this.geometries.set(kind,geo);return geo}
 ship(group,kind){const T=this.T;group.children[0].geometry=this.shape(kind);group.children[0].castShadow=true;group.children[0].receiveShadow=true;const detail=new T.Group;detail.userData.pcDetail=true;const shell=new T.Mesh(this.shape(kind),this.panel);shell.scale.set(.72,.32,.72);shell.position.y=.06;shell.castShadow=true;detail.add(shell);const vents=new T.Instanced(this.rib,this.dark,10);for(let i=0;i<10;i++){this.unit.position.set((i<5?-1:1)*(.09+i%5*.022),.1,.12);this.unit.scale.set(1,1,1);this.unit.rotation.set(0,0,0);this.unit.updateMatrix();vents.setMatrixAt(i,this.unit.matrix)}detail.add(vents);group.add(detail);if(kind==='orb'){const hoop=new T.Mesh(new T.Torus(.21,.018,6,32),this.edge);hoop.rotation.x=-Math.PI/2;hoop.position.y=.1;group.add(hoop)}if(kind==='carrier'){for(const side of [-1,1]){const pod=new T.Mesh(new T.Capsule(.055,.3,4,8),this.panel);pod.rotation.x=Math.PI/2;pod.position.set(side*.26,.08,.04);pod.castShadow=true;group.add(pod)}}}
 terrain(island,index){const T=this.T;island.receiveShadow=true;island.castShadow=true;const strata=new T.Mesh(island.geometry,this.stone);strata.scale.set(.89,1.3,.89);strata.position.y=-.18;island.add(strata);const city=new T.Instanced(this.block,this.edge,32);city.userData.pcDetail=true;city.castShadow=true;city.receiveShadow=true;for(let j=0;j<32;j++){const angle=j*2.399;this.unit.position.set(Math.cos(angle)*(.15+j%4*.085),.07,Math.sin(angle)*(.15+j%4*.085));this.unit.scale.set(1,j%5*.4+.5,1);this.unit.rotation.set(0,Math.floor(j%4)*Math.PI/2,0);this.unit.updateMatrix();city.setMatrixAt(j,this.unit.matrix)}island.add(city);const ring=new T.Mesh(new T.Torus(.26,.016,5,48),this.dark);ring.rotation.x=-Math.PI/2;ring.position.y=.03;island.add(ring)}
}
